import { ScriptError, obj, parseProgram, type Program } from './lang'
import {
  DEFAULT_CAMERA,
  DEFAULT_FOG,
  DEFAULT_LIGHT,
  MOST_TRIANGLES,
  SX,
  SY,
  box,
  claimPixel,
  composite,
