{
  "name": "toons",
  "version": "0.1.0",
  "description": "Animated cartoons of what Claude is doing, drawn under the spinner while it works",
  "author": {
    "name": "Anshu Chimala"
  },
  "license": "MIT",
  "userConfig": {
    "model": {
      "type": "string",
      "title": "Toons: director model",
      "description": "The model that watches Claude work and directs the cartoons. Haiku is cheapest; Opus is the most inventive. /toons settings shows what each costs.",
      "default": "claude-sonnet-5-5",
      "options": [
        "claude-haiku-4-5",
        "claude-sonnet-5-5",
        "claude-opus-5-5"
      ]
    },
    "styles": {
      "type": "string",
      "title": "Toons: scene styles",
      "description": "Which ways the scenes are drawn: a mix (3D most often, pixel art, text art), one style only, or everything but 3D.",
      "default": "mix",
      "options": [
        "mix",
        "3D",
        "pixel art",
        "text art",
        "no 3D"
      ]
    },
    "thinking": {
      "type": "string",
      "title": "Toons: director thinks",
      "description": "Whether the director model thinks before each scene. Off is cheaper (thinking is billed as output); on may give more inventive scenes. Opus always thinks.",
      "default": "off",
      "options": [
        "off",
        "on"
      ]
    },
    "library": {
      "type": "string",
      "title": "Toons: scenes",
      "description": "Where scenes come from. \"ready-made only\" uses the scenes that ship with the plugin and spends no tokens. \"mix\" (the default) adds a freshly drawn scene for news like a new task or a failure, about 1-3% on top of what Claude Code uses. \"fresh only\" draws every scene new, which uses several times more tokens.",
      "default": "mix",
      "options": [
        "ready-made only",
        "mix",
        "fresh only"
      ]
    },
    "pace": {
      "type": "string",
      "title": "Toons: new scene",
      "description": "How often a new scene is requested while Claude works. Slower is cheaper; each scene keeps animating until the next arrives.",
      "default": "every 15 seconds",
      "options": [
        "as fast as possible",
        "every 15 seconds",
        "every 30 seconds",
        "every minute"
      ]
    }
  }
}
